-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/hiddenQuests/Trust_Abquhbah.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Abquhbah.lua",["SHA256"]="346cf79bd71af0f2f4fdeaaf5d63d2ba1eae24a7a9e52d36a9f4229a3bb5b9b0",["Text"]="-----------------------------------\n-- Trust: Abquhbah\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustAbquhbah')\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.ABQUHBAH) and\n                not player:findItem(xi.item.CIPHER_OF_ABQUHBAHS_ALTER_EGO) and\n                player:hasCompletedMission(xi.mission.log_id.TOAU, xi.mission.id.toau.IMMORTAL_SENTRIES) and\n                player:getCurrentMission(xi.mission.log_id.ROV) >= xi.mission.id.rov.EVER_FORWARD\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Abquhbah'] =\n            {\n                onTrigger = function(player, npc)\n                    local hasTrustPermit = xi.trust.hasPermit(player) and 1 or 0\n\n                    return quest:progressEvent(170, { [1] = hasTrustPermit, [2] = player:getNation(), text_table = 0 })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [170] = function(player, csid, option, npc)\n                    if xi.trust.hasPermit(player) then\n                        npcUtil.giveItem(player, xi.item.CIPHER_OF_ABQUHBAHS_ALTER_EGO)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Cherukiki.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Cherukiki.lua",["SHA256"]="4024cbce579c49f5b965004e040cc3a66102523c819b43cad309457eac90e01a",["Text"]="-----------------------------------\n-- Trust: Cherukiki\n-----------------------------------\n-- Taillegeas : !pos 31.000 1.995 57.971 243\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustCherukiki')\n\nlocal trustMemory = function(player)\n    local memories = 0\n\n    -- TODO: Does she have these?\n\n    return memories\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.CHERUKIKI) and\n                (\n                    -- Between these missions\n                    (player:getCurrentMission(xi.mission.log_id.COP) > xi.mission.id.cop.CHAINS_AND_BONDS and\n                    player:getCurrentMission(xi.mission.log_id.COP) < xi.mission.id.cop.THE_WARRIORS_PATH)\n                    or\n                    -- On Dawn, but past \"the boss\"\n                    (player:getCurrentMission(xi.mission.log_id.COP) == xi.mission.id.cop.DAWN and\n                    xi.mission.getVar(player, xi.mission.log_id.COP, xi.mission.id.cop.DAWN, 'Status') >= 2)\n                    or\n                    -- Past Dawn\n                    player:getCurrentMission(xi.mission.log_id.COP) > xi.mission.id.cop.DAWN\n                )\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Taillegeas'] =\n            {\n                onTrigger = function(player, npc, trade)\n                    return quest:progressEvent(10235, 0, 0, 0, trustMemory(player))\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10235] = function(player, csid, option, npc)\n                    if option == 2 and quest:complete(player) then\n                        player:addSpell(xi.magic.spell.CHERUKIKI, { silentLog = true })\n                        player:messageSpecial(ruludeID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.CHERUKIKI)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Halver.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Halver.lua",["SHA256"]="d65a9e3608b672ccd6ab6d59e7aee1dc58fdb39eb6db8fa2bc636a90f9bcb340",["Text"]="-----------------------------------\n-- Trust: Halver\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustHalver')\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.HALVER) and\n                not player:findItem(xi.item.CIPHER_OF_HALVERS_ALTER_EGO) and\n                player:hasCompletedMission(xi.mission.log_id.ROV, xi.mission.id.rov.THE_PATH_UNTRAVELED)\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Halver'] =\n            {\n                onTrigger = function(player, npc)\n                    -- NOTE: No cap has been provided to determine if there is separate dialogue.\n                    -- This exists as a stopgap to ensure that the player can receive the item in case of full inventory, or having already progressed.\n\n                    npcUtil.giveItem(player, xi.item.CIPHER_OF_HALVERS_ALTER_EGO)\n                    return quest:noAction()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Ingrid.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Ingrid.lua",["SHA256"]="0dc72b81f639b696694a4c490a7a95e98def5242ae2556f9cd2d748e8b8454ae",["Text"]="-----------------------------------\n-- Trust: Ingrid\n-----------------------------------\nlocal easternAdoulinID = zones[xi.zone.EASTERN_ADOULIN]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustIngrid')\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.INGRID) and\n                player:hasCompletedMission(xi.mission.log_id.SOA, xi.mission.id.soa.THE_MERCILESS_ONE)\n        end,\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Rigobertine'] =\n            {\n                onTrigger = function(player, npc)\n                    -- TODO: These parameters may have no impact on the event, and were captured\n                    -- immediately after completing \"The Merciless One\" and receiving eternal flame\n                    -- keyitem.\n\n                    return quest:event(5062, 257, 0, 0, 255, 255, 4352, 1)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5062] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:addSpell(xi.magic.spell.INGRID, { silentLog = true })\n\n                        player:messageSpecial(easternAdoulinID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.INGRID)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Maat.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Maat.lua",["SHA256"]="ec91c7af41c95902c4c4442b4d945b0c2018ac36bb1299559c496c65d63e75c3",["Text"]="-----------------------------------\n-- Trust: Maat\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustMaat')\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.MAAT)\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    if utils.mask.countBits(player:getCharVar('maatsCap'), 16) >= 6 then\n                        return quest:event(10241)\n                    else\n                        return quest:event(10242)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10241] = function(player, csid, option, npc)\n                    if option == 2 and quest:complete(player) then\n                        player:addSpell(xi.magic.spell.MAAT, { silentLog = true })\n                        player:messageSpecial(ruludeID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.MAAT)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Nashmeira.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Nashmeira.lua",["SHA256"]="5482d3eaf79eae1b1b1de0c1367474d92c6b552efcead5cde2b1c769a2acb3de",["Text"]="-----------------------------------\n-- Trust: Nashmeira\n-----------------------------------\nlocal whitegateID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\nlocal quest = HiddenQuest:new('TrustNashmeira')\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.NASHMEIRA) and\n                player:hasCompletedMission(xi.mission.log_id.TOAU, xi.mission.id.toau.THE_EMPRESS_CROWNED)\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Imperial_Whitegate'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(5092, { text_table = 0 })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5092] = function(player, csid, option, npc)\n                    if option == 2 and quest:complete(player) then\n                        player:addSpell(xi.magic.spell.NASHMEIRA, { silentLog = true })\n                        player:messageSpecial(whitegateID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.NASHMEIRA)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Prishe.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Prishe.lua",["SHA256"]="199fffda3aff41ea23a35cf4fb8c47248eff2b218829c0eed9f691316973a793",["Text"]="-----------------------------------\n-- Trust: Prishe\n-----------------------------------\n-- Walnut Door : !pos 117.029 -42.799 41.997 26\n-----------------------------------\nlocal tavnaziaID = zones[xi.zone.TAVNAZIAN_SAFEHOLD]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustPrishe')\n\nlocal trustMemory = function(player)\n    local memories = 0\n\n    -- Now that I think about it, I remember a time when some old jeweler over in Jeuno was going on and on about what \"love\" really is.\n    -- You know what I learned from him? That love ain't something you know about until it hits you. So that means I don't know what love is?\n    if player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.IN_THE_MOOD_FOR_LOVE) then\n        memories = memories + 2\n    end\n\n    -- But I recall sharing something with a certain young girl...\n    -- Animals have hearts and souls, just like people do, and their hearts are much more pure than ours.\n    -- Now if only I were as pure as a moogle, then maybe...\n    -- Ah, screw it all! What's this weird heat coming from my cheeks?\n    if player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.A_CHOCOBOS_TALE) then\n        memories = memories + 4\n    end\n\n    -- [Well, then/Hmm... Come to think of it], the two of us make one hell of a team, don't you agree?\n    -- Although a certain someone yelled at me not to leap without looking all the time.\n    -- Let me share with you a little something. There's this geezer over in Jeuno, always with his fishing rod by the docks, who musta stared daggers at me for hours on end.\n    -- You'd picture he'd've just told me to be careful, but oh no!\n    -- If it were you in a pit of snakes, though, I wouldn't care what any old fart would have to say! I'd throw myself in after you in a heartbeat!\n    if player:hasCompletedMission(xi.questLog.JEUNO, xi.quest.id.jeuno.HOOK_LINE_AND_SINKER) then\n        memories = memories + 8\n    end\n\n    -- The Shadow Lord, Kam'lanaut, Eald'narche, Nag'Molada...doesn't matter one bit to me.\n    -- They may have succumbed--but we didn't. And you remember why, don't you?\n    -- The light that brought us into this world shines brighter than the sun, and continues to bless the world, its people, and our hearts.\n    if player:hasCompletedMission(xi.questLog.JEUNO, xi.quest.id.jeuno.APOCALYPSE_NIGH) then\n        memories = memories + 16\n    end\n\n    return memories\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.PRISHE) and\n                (player:getCurrentMission(xi.mission.log_id.COP) > xi.mission.id.cop.DAWN and\n                xi.mission.getVar(player, xi.mission.log_id.COP, xi.mission.id.cop.DAWN, 'Status') >= 5)\n                -- TODO: Additional conditions\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            -- Walnut Door\n            ['_0qa'] =\n            {\n                onTrigger = function(player, npc, trade)\n                    return quest:progressEvent(633, 0, 0, 0, trustMemory(player))\n                end,\n            },\n\n            onEventFinish =\n            {\n                [633] = function(player, csid, option, npc)\n                    if option == 2 and quest:complete(player) then\n                        player:addSpell(xi.magic.spell.PRISHE, { silentLog = true })\n                        player:messageSpecial(tavnaziaID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.PRISHE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Semih.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Semih.lua",["SHA256"]="d6c04ce96d071d4517aa5bcebadd303bdced0f06f3104847f2d0018854a036f5",["Text"]="-----------------------------------\n-- Trust: Semih\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustSemih')\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.SEMIH_LAFIHNA) and\n                not player:findItem(xi.item.CIPHER_OF_SEMIHS_ALTER_EGO) and\n                player:hasCompletedMission(xi.mission.log_id.ROV, xi.mission.id.rov.THE_PATH_UNTRAVELED)\n        end,\n\n        [xi.zone.HEAVENS_TOWER] =\n        {\n            ['Kupipi'] =\n            {\n                onTrigger = function(player, npc)\n                    -- NOTE: No cap has been provided to determine if there is separate dialogue.\n                    -- This exists as a stopgap to ensure that the player can receive the item in case of full inventory, or having already progressed.\n\n                    npcUtil.giveItem(player, xi.item.CIPHER_OF_SEMIHS_ALTER_EGO)\n                    return quest:noAction()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Shantotto.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Shantotto.lua",["SHA256"]="6c5822e9f90fdd4ab085601a8730be6a541de21f98a859eda32d7df4c7b5d57c",["Text"]="-----------------------------------\n-- Trust: Shantotto\n-----------------------------------\n-- Shantotto : !pos 122 -2 112 239\n-----------------------------------\nlocal wallsID = zones[xi.zone.WINDURST_WALLS]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustShantotto')\n\nlocal requiredTrusts =\n{\n    xi.magic.spell.KUPIPI,\n    xi.magic.spell.NANAA_MIHGO,\n    xi.magic.spell.AJIDO_MARUJIDO,\n    xi.magic.spell.EXCENMILLE,\n    xi.magic.spell.CURILLA,\n    xi.magic.spell.TRION,\n    xi.magic.spell.AYAME,\n    xi.magic.spell.NAJI,\n    xi.magic.spell.VOLKER,\n}\n\nlocal function hasRequiredTrusts(player)\n    for _, trustSpellId in ipairs(requiredTrusts) do\n        if not player:hasSpell(trustSpellId) then\n            return false\n        end\n    end\n\n    return true\nend\n\nlocal trustMemory = function(player)\n    local memories = 0\n    --[[ TODO\n    -- 2 - The Three Kingdoms\n    if player:hasCompletedMission(xi.mission.log_id.SANDORIA, xi.mission.id.sandoria.JOURNEY_TO_BASTOK2) or player:hasCompletedMission(xi.mission.log_id.WINDURST, xi.mission.id.windurst.THE_THREE_KINGDOMS_BASTOK2) then\n        memories = memories + 2\n    end\n    -- 4 - Where Two Paths Converge\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.WHERE_TWO_PATHS_CONVERGE) then\n        memories = memories + 4\n    end\n    -- 8 - The Pirate's Cove\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.THE_PIRATES_COVE) then\n        memories = memories + 8\n    end\n    -- 16 - Ayame and Kaede\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.AYAME_AND_KAEDE) then\n        memories = memories + 16\n    end\n    -- 32 - Light of Judgement\n    if player:hasCompletedMission(xi.mission.log_id.TOAU, xi.mission.id.toau.LIGHT_OF_JUDGMENT) then\n        memories = memories + 32\n    end\n    -- 64 - True Strength\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.TRUE_STRENGTH) then\n        memories = memories + 64\n    end\n    ]]--\n\n    -- Kill a Taru under the gun\n    -- Defeated Shadowlord\n    -- Saving Star Sibyl\n    -- Grade, came up in spades\n    -- Bring back Prishe\n    -- Yoran Oran: No Heir\n    -- Incident with Ragnarok\n    -- Chocobo Races\n    -- Markovich\n    -- Puppet Twin battle\n    -- Yoran-Oran and Koru-Moru\n    -- Grimy Hat\n    return memories\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                not player:hasSpell(xi.magic.spell.SHANTOTTO) and\n                player:hasKeyItem(xi.keyItem.WINDURST_TRUST_PERMIT)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_A_GOLEM) and\n                        hasRequiredTrusts(player)\n                    then\n                        return quest:progressEvent(529, { [3] = trustMemory(player), [7] = 1 })\n                    else\n                        return quest:event(529):importantEvent()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [529] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:addSpell(xi.magic.spell.SHANTOTTO, { silentLog = true })\n                        player:messageSpecial(wallsID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.SHANTOTTO)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_ShikareeZ.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_ShikareeZ.lua",["SHA256"]="a76fd43cab29c4558edce3d1340a8d5b29ea76783e19e4d58dce7ef26d876437",["Text"]="-----------------------------------\n-- Trust: Shikaree Z\n-----------------------------------\n-- Perih Vashai !gotoid 17764470 / !pos 117.5 -3.7 90.453 241\n-----------------------------------\nlocal woodsID = zones[xi.zone.WINDURST_WOODS]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustShikareeZ')\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.SHIKAREE_Z) and\n                player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THREE_PATHS) and\n                -- TODO BG WIKI States acquisition can be blocked while Shikaree Z is \"out of town\".\n                --      Verify which Missions this comment refers to, though likely the following:\n                --      FLAMES_IN_THE_DARKNESS, FIRE_IN_THE_EYES_OF_MEN, A_FATE_DECIDED\n                --      https://www.bg-wiki.com/ffxi/Promathia_Mission_5-3\n                --      https://www.bg-wiki.com/ffxi/BGWiki:Trusts#Shikaree_Z\n                not (player:getCurrentMission(xi.mission.log_id.COP) >= xi.mission.id.cop.FLAMES_IN_THE_DARKNESS and\n                player:getCurrentMission(xi.mission.log_id.COP) <= xi.mission.id.cop.FIRE_IN_THE_EYES_OF_MEN) and\n                player:getCurrentMission(xi.mission.log_id.COP) ~= xi.mission.id.cop.A_FATE_DECIDED and\n                player:hasKeyItem(xi.keyItem.WINDURST_TRUST_PERMIT)\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Perih_Vashai'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(869)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [869] = function(player, csid, option, npc)\n                    if xi.trust.hasPermit(player) then\n                        player:addSpell(xi.magic.spell.SHIKAREE_Z, { silentLog = true })\n                        player:messageSpecial(woodsID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.SHIKAREE_Z)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Ulmia.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Ulmia.lua",["SHA256"]="ecfa3d37887e7d43b9518cbe2bd4ff3ba8334432cdf74a1b2fc2559e2cc84987",["Text"]="-----------------------------------\n-- Trust: Ulmia\n-----------------------------------\n-- Dilapidated Gate : !pos 260.000 7.319 -440.001 25\n-----------------------------------\nlocal misareauxID = zones[xi.zone.MISAREAUX_COAST]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustUlmia')\n\nlocal trustMemory = function(player)\n    local memories = 0\n\n    -- When I sang the Lay of the Immortals before the fifth crystal, it stirred up emotions within me.\n    -- It dawned on me that it was not the oppressive weight of darkness that brought us together, but the holy light of the crystals.\n    -- So now...\n    if player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.APOCALYPSE_NIGH) then\n        memories = memories + 2\n    end\n\n    return memories\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                xi.trust.hasPermit(player) and\n                not player:hasSpell(xi.magic.spell.ULMIA) and\n                -- On Dawn, but past \"the boss\"\n                (player:getCurrentMission(xi.mission.log_id.COP) > xi.mission.id.cop.DAWN and\n                xi.mission.getVar(player, xi.mission.log_id.COP, xi.mission.id.cop.DAWN, 'Status') >= 2)\n                -- TODO: Additional conditions\n        end,\n\n        [xi.zone.MISAREAUX_COAST] =\n        {\n            -- Dilapidated Gate\n            ['_0p0'] =\n            {\n                onTrigger = function(player, npc, trade)\n                    return quest:progressEvent(560, 0, 0, 0, trustMemory(player))\n                end,\n            },\n\n            onEventFinish =\n            {\n                [560] = function(player, csid, option, npc)\n                    if option == 2 and quest:complete(player) then\n                        player:addSpell(xi.magic.spell.ULMIA, { silentLog = true })\n                        player:messageSpecial(misareauxID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.ULMIA)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Trust_Zeid_II.lua"]={["Path"]="scripts/quests/hiddenQuests/Trust_Zeid_II.lua",["SHA256"]="f9e4cb4b44266ffddb5504a13aab16d9ff09d59881b626092977e7b05ab1a406",["Text"]="-----------------------------------\n-- Trust: Zeid II\n-----------------------------------\n\nlocal quest = HiddenQuest:new('TrustZeidII')\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n                not player:hasSpell(xi.magic.spell.ZEID_II) and\n                not player:findItem(xi.item.CIPHER_OF_ZEIDS_ALTER_EGO_II) and\n                player:hasCompletedMission(xi.mission.log_id.ROV, xi.mission.id.rov.VOLTO_OSCURO)\n        end,\n\n        [xi.zone.NORG] =\n        {\n            ['_700'] =\n            {\n                onTrigger = function(player, npc)\n                    -- NOTE: No cap has been provided to determine if there is separate dialogue.  This\n                    -- exists as a stopgap to ensure that the player can receive the item in case of full\n                    -- inventory, or having already progressed.\n\n                    npcUtil.giveItem(player, xi.item.CIPHER_OF_ZEIDS_ALTER_EGO_II)\n                    return quest:noAction()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Tutorial_Quest.lua"]={["Path"]="scripts/quests/hiddenQuests/Tutorial_Quest.lua",["SHA256"]="b6349f72261c234b23383781f1ffe9a71b0f19517e5b647e440bbab5f352b2bd",["Text"]="-----------------------------------\n-- Tutorial Mini-Quest\n-----------------------------------\nlocal quest = HiddenQuest:new('Tutorial')\n\nlocal function hasLearntWeaponskill(player)\n    for skillId = xi.skill.HAND_TO_HAND, xi.skill.STAFF do\n        if player:getSkillLevel(skillId) >= 5 then\n            return true\n        end\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    -- Step 0 -> Introduction.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 0\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] = quest:progressEvent(719),\n\n            onEventFinish =\n            {\n                [719] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] = quest:progressEvent(3662),\n\n            onEventFinish =\n            {\n                [3662] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] = quest:progressEvent(1010),\n\n            onEventFinish =\n            {\n                [1010] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Step 1 -> Instruct to get Signet.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 1\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] = quest:progressEvent(697),\n\n            onEventFinish =\n            {\n                [697] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] = quest:progressEvent(3640),\n\n            onEventFinish =\n            {\n                [3640] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] = quest:progressEvent(988),\n\n            onEventFinish =\n            {\n                [988] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Step 2 -> Talk to NPC after getting Signet (Reward: Meat Jerky x6.). Instruct to eat.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 2\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasStatusEffect(xi.effect.SIGNET) then\n                        return quest:progressEvent(699)\n                    else\n                        return quest:event(698)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [699] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.STRIP_OF_MEAT_JERKY, 6 } }) then\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasStatusEffect(xi.effect.SIGNET) then\n                        return quest:progressEvent(3642)\n                    else\n                        return quest:event(3641)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3642] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.STRIP_OF_MEAT_JERKY, 6 } }) then\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasStatusEffect(xi.effect.SIGNET) then\n                        return quest:progressEvent(990)\n                    else\n                        return quest:event(989)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [990] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.STRIP_OF_MEAT_JERKY, 6 } }) then\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Step 3 -> Talk to NPC after having eaten. Instruct to learn a weaponskill.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 3\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasStatusEffect(xi.effect.FOOD) then\n                        return quest:progressEvent(701)\n                    else\n                        return quest:event(700)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [701] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasStatusEffect(xi.effect.FOOD) then\n                        return quest:progressEvent(3644)\n                    else\n                        return quest:event(3643)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3644] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasStatusEffect(xi.effect.FOOD) then\n                        return quest:progressEvent(992)\n                    else\n                        return quest:event(991)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [992] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    -- Step 4 -> Talk to NPC after learning a Weaponskill (Reward: 100 gil). Instruct to activate Records of Eminence. NOTE: Retail does NOT check for weaponskill usage.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 4\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if hasLearntWeaponskill(player) then\n                        return quest:progressEvent(703)\n                    else\n                        return quest:event(702)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [703] = function(player, csid, option, npc)\n                    npcUtil.giveCurrency(player, 'gil', 100 * xi.settings.main.GIL_RATE)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if hasLearntWeaponskill(player) then\n                        return quest:progressEvent(3646)\n                    else\n                        return quest:event(3645)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3646] = function(player, csid, option, npc)\n                    npcUtil.giveCurrency(player, 'gil', 100 * xi.settings.main.GIL_RATE)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if hasLearntWeaponskill(player) then\n                        return quest:progressEvent(994)\n                    else\n                        return quest:event(993)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [994] = function(player, csid, option, npc)\n                    npcUtil.giveCurrency(player, 'gil', 100 * xi.settings.main.GIL_RATE)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n    },\n\n    -- Step 5 -> Talk to NPC after getting Memorandoll (Reward: Crystal and 2 items). Instruct to check the AH.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 5\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.MEMORANDOLL) then\n                        return quest:progressEvent(705)\n                    else\n                        return quest:event(704)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [705] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.LIZARD_TAIL, 1 }, { xi.item.POT_OF_HONEY, 1 }, { xi.item.FIRE_CRYSTAL, 1 } }) then\n                        quest:setVar(player, 'Prog', 6)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.MEMORANDOLL) then\n                        return quest:progressEvent(3648)\n                    else\n                        return quest:event(3647)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3648] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.CHUNK_OF_ROCK_SALT, 1 }, { xi.item.SLICE_OF_HARE_MEAT, 1 }, { xi.item.FIRE_CRYSTAL, 1 } }) then\n                        quest:setVar(player, 'Prog', 6)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.MEMORANDOLL) then\n                        return quest:progressEvent(996)\n                    else\n                        return quest:event(995)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [996] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.BIRD_EGG, 1 }, { xi.item.POT_OF_HONEY, 1 }, { xi.item.WATER_CRYSTAL, 1 } }) then\n                        quest:setVar(player, 'Prog', 6)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Step 6 -> Talk to NPC after checking the AH (Reward: Conquest promotion voucher). Instruct to reach level 5.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 6\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:progressEvent(707)\n                    else\n                        return quest:event(706)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [707] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CONQUEST_PROMOTION_VOUCHER)\n                    quest:setVar(player, 'Prog', 7)\n                    quest:setVar(player, 'Option', 0)\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n        },\n\n        [xi.zone.EASTERN_ADOULIN] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n        },\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n        },\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n        },\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:progressEvent(3650)\n                    else\n                        return quest:event(3649)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3650] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CONQUEST_PROMOTION_VOUCHER)\n                    quest:setVar(player, 'Prog', 7)\n                    quest:setVar(player, 'Option', 0)\n                end,\n            },\n        },\n\n        [xi.zone.WESTERN_ADOULIN] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Auction_Counter'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'Option', 1)\n                    player:sendMenu(xi.menuType.AUCTION)\n                    return quest:noAction()\n                end,\n            },\n\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:progressEvent(998)\n                    else\n                        return quest:event(997)\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [998] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CONQUEST_PROMOTION_VOUCHER)\n                    quest:setVar(player, 'Prog', 7)\n                    quest:setVar(player, 'Option', 0)\n                end,\n            },\n        },\n    },\n\n    -- Step 7 -> Talk to NPC after reaching level 5 (Reward: Raising Earring). Instruct to get nation's trust permit.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 7\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= 5 then\n                        return quest:progressEvent(709)\n                    else\n                        return quest:event(708)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [709] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.RAISING_EARRING) then\n                        quest:setVar(player, 'Prog', 8)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= 5 then\n                        return quest:progressEvent(3652)\n                    else\n                        return quest:event(3651)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3652] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.RAISING_EARRING) then\n                        quest:setVar(player, 'Prog', 8)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= 5 then\n                        return quest:progressEvent(1000)\n                    else\n                        return quest:event(999)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1000] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.RAISING_EARRING) then\n                        quest:setVar(player, 'Prog', 8)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Step 8 -> Talk to NPC after getting nation trust permit (Reward: Warp Ring). Instruct to use Survival guide.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 8\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.BASTOK_TRUST_PERMIT) then\n                        return quest:progressEvent(711)\n                    else\n                        return quest:event(710)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [711] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.WARP_RING) then\n                        quest:setVar(player, 'Prog', 9)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.SAN_DORIA_TRUST_PERMIT) then\n                        return quest:progressEvent(3654)\n                    else\n                        return quest:event(3653)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3654] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.WARP_RING) then\n                        quest:setVar(player, 'Prog', 9)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.WINDURST_TRUST_PERMIT) then\n                        return quest:progressEvent(1002)\n                    else\n                        return quest:event(1001)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1002] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.WARP_RING) then\n                        quest:setVar(player, 'Prog', 9)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Step 9 -> Talk to NPC after checking Survival guides in order (Reward: Saltena x12). Instruct to reach level 18. NOTE: Retail only cares for checking the survival guide in city and in outpost.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 9\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('TutorialBypass') >= 2 then\n                        return quest:progressEvent(713, xi.nation.BASTOK)\n                    else\n                        return quest:event(712, xi.nation.BASTOK)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [713] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.SALTENA, 12 } }) then\n                        quest:setVar(player, 'Prog', 10)\n                        player:setCharVar('TutorialBypass', 0)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Survival_Guide'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('TutorialBypass') == 0 then\n                        player:setCharVar('TutorialBypass', 1)\n                        return xi.survivalGuide.onTrigger(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTH_GUSTABERG] =\n        {\n            ['Survival_Guide'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('TutorialBypass') == 1 then\n                        player:setCharVar('TutorialBypass', 2)\n                        return xi.survivalGuide.onTrigger(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Survival_Guide'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('TutorialBypass') == 0 then\n                        player:setCharVar('TutorialBypass', 1)\n                        return xi.survivalGuide.onTrigger(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Survival_Guide'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('TutorialBypass') == 0 then\n                        player:setCharVar('TutorialBypass', 1)\n                        return xi.survivalGuide.onTrigger(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('TutorialBypass') >= 2 then\n                        return quest:progressEvent(3656, xi.nation.SANDORIA)\n                    else\n                        return quest:event(3655, xi.nation.SANDORIA)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3656] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.SALTENA, 12 } }) then\n                        quest:setVar(player, 'Prog', 10)\n                        player:setCharVar('TutorialBypass', 0)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Survival_Guide'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('TutorialBypass') == 1 then\n                        player:setCharVar('TutorialBypass', 2)\n                        return xi.survivalGuide.onTrigger(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WEST_SARUTABARUTA] =\n        {\n            ['Survival_Guide'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('TutorialBypass') == 1 then\n                        player:setCharVar('TutorialBypass', 2)\n                        return xi.survivalGuide.onTrigger(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('TutorialBypass') >= 2 then\n                        return quest:progressEvent(1004, xi.nation.WINDURST)\n                    else\n                        return quest:event(1003, xi.nation.WINDURST)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1004] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.SALTENA, 12 } }) then\n                        quest:setVar(player, 'Prog', 10)\n                        player:setCharVar('TutorialBypass', 0)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Step 10 -> Talk to NPC after reaching level 18 (Reward: Copper A.M.A.N. Voucher). Instruct to get and set a subjob.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 10\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= 18 then\n                        return quest:progressEvent(715, xi.nation.BASTOK)\n                    else\n                        return quest:event(714)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [715] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.COPPER_AMAN_VOUCHER) then\n                        quest:setVar(player, 'Prog', 11)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= 18 then\n                        return quest:progressEvent(3658, xi.nation.SANDORIA)\n                    else\n                        return quest:event(3657)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3658] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.COPPER_AMAN_VOUCHER) then\n                        quest:setVar(player, 'Prog', 11)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= 18 then\n                        return quest:progressEvent(1006, xi.nation.WINDURST)\n                    else\n                        return quest:event(1005)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1006] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.COPPER_AMAN_VOUCHER) then\n                        quest:setVar(player, 'Prog', 11)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Step 11 -> Talk to NPC after setting a subjob (Reward: Chocopass x12, Echad Ring).\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 11\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getSubLvl() >= 1 then\n                        return quest:progressEvent(717)\n                    else\n                        return quest:event(716, xi.nation.BASTOK)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [717] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.FREE_CHOCOPASS, 12 }, { xi.item.ECHAD_RING, 1 } }) then\n                        quest:setVar(player, 'Prog', 12)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getSubLvl() >= 1 then\n                        return quest:progressEvent(3660)\n                    else\n                        return quest:event(3659, xi.nation.SANDORIA)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3660] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.FREE_CHOCOPASS, 12 }, { xi.item.ECHAD_RING, 1 } }) then\n                        quest:setVar(player, 'Prog', 12)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getSubLvl() >= 1 then\n                        return quest:progressEvent(1008)\n                    else\n                        return quest:event(1007, xi.nation.WINDURST)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1008] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, { { xi.item.FREE_CHOCOPASS, 12 }, { xi.item.ECHAD_RING, 1 } }) then\n                        quest:setVar(player, 'Prog', 12)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Default dialog after completing tutorial.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog == 12\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gulldago'] = quest:event(718),\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Alaune'] = quest:event(3661),\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Selele'] = quest:event(1009),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/A_Candlelight_Vigil.lua"]={["Path"]="scripts/quests/jeuno/A_Candlelight_Vigil.lua",["SHA256"]="88819c69ed4bd67a8d23422ecf19411717694141f81b3db9fe82b0d6fe8c948d",["Text"]="-----------------------------------\n-- A Candlelight Vigil\n-----------------------------------\n-- !addquest 3 6\n-- Ilumida : !pos -75 -1 58 244\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.A_CANDLELIGHT_VIGIL)\n\nquest.reward =\n{\n    item     = xi.item.FLOWER_NECKLACE,\n    title    = xi.title.ACTIVIST_FOR_KINDNESS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 4\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Ilumida'] =\n            {\n                onTrigger = function(player, npc)\n                    local questOption = quest:getVar(player, 'Option')\n\n                    if questOption == 0 then\n                        return quest:progressEvent(192)\n                    elseif questOption == 1 then\n                        return quest:progressEvent(193)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [192] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n\n                [193] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Option', 0)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Ilumida'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.HOLY_CANDLE) then\n                        return quest:progressEvent(194)\n                    else\n                        return quest:progressEvent(191)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [194] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 13)\n                        player:addFame(xi.fameArea.BASTOK, 13)\n                        player:addFame(xi.fameArea.WINDURST, 13)\n                        player:delKeyItem(xi.keyItem.HOLY_CANDLE)\n                        xi.quest.setMustZone(player, xi.questLog.JEUNO, xi.quest.id.jeuno.SEARCHING_FOR_THE_RIGHT_WORDS)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/A_Chocobos_Tale.lua"]={["Path"]="scripts/quests/jeuno/A_Chocobos_Tale.lua",["SHA256"]="08d0940b65e435a9d13d7159255044bc208ac72b7597a42d3780739cb2d0a06e",["Text"]="-----------------------------------\n-- A Chocobo's Tale\n-----------------------------------\n-- Log ID: 3, Quest ID: 72\n-- Nevela       : !pos -60.114 0 81.125 244\n-- Wobke        : !pos 29.028 0.874 -111.626 234\n-- Outpost Gate : !pos 473.566 23.421 413.134 109\n-- qm           : !pos -39.370 -11.093 307.285 105\n-----------------------------------\nlocal batalliaID = zones[xi.zone.BATALLIA_DOWNS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.A_CHOCOBOS_TALE)\n\nquest.reward =\n{\n    gil      = 5200,\n    title    = xi.title.CHOCOBO_LOVE_GURU,\n}\n\nlocal function isNMSpawned()\n    for nmId = batalliaID.mob.BADSHAH_OFFSET, batalliaID.mob.BADSHAH_OFFSET + 4 do\n        if GetMobByID(nmId):isSpawned() then\n            return true\n        end\n    end\n\n    return false\nend\n\nlocal function isNMDefeated()\n    for nmId = batalliaID.mob.BADSHAH_OFFSET, batalliaID.mob.BADSHAH_OFFSET + 4 do\n        local nmMob = GetMobByID(nmId)\n\n        if\n            nmMob and\n            (nmMob:isDead() or\n            not nmMob:isSpawned())\n        then\n            return true\n        end\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.A_VESSEL_WITHOUT_A_CAPTAIN)\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Nevela'] = quest:progressEvent(10015),\n\n            onEventFinish =\n            {\n                [10015] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Nevela'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(10017)\n                    else\n                        return quest:event(10016)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10017] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:delKeyItem(xi.keyItem.SILVER_COMETS_COLLAR)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Wobke'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(245)\n                    elseif questProgress <= 2 then\n                        return quest:event(246)\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(247, 0, xi.item.BOTTLE_OF_WARDING_OIL)\n                    else\n                        return quest:event(248)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [245] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [247] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.PASHHOW_MARSHLANDS] =\n        {\n            ['Outpost_Gate'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { { xi.item.BOTTLE_OF_WARDING_OIL, 3 } }) and\n                        quest:getVar(player, 'Prog') == 2\n                    then\n                        return quest:progressEvent(22)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    -- TODO: The followup after CS 21 may be different, and needs capture.\n\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(21, 0, xi.item.BOTTLE_OF_WARDING_OIL)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [21] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [22] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.BATALLIA_DOWNS] =\n        {\n            ['qm_chocobotale'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not isNMSpawned() and\n                        quest:getVar(player, 'Prog') == 4\n                    then\n                        if quest:getLocalVar(player, 'nmDefeated') == 1 then\n                            quest:setVar(player, 'Prog', 5)\n\n                            return quest:keyItem(xi.keyItem.SILVER_COMETS_COLLAR)\n                        else\n                            for nmId = batalliaID.mob.BADSHAH_OFFSET, batalliaID.mob.BADSHAH_OFFSET + 4 do\n                                SpawnMob(nmId):updateClaim(player)\n                            end\n\n                            return quest:messageSpecial(batalliaID.text.YOU_ARE_BEING_ATTACKED)\n                        end\n                    end\n                end,\n            },\n\n            ['Badshah'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if\n                        isNMDefeated() and\n                        quest:getVar(player, 'Prog') == 4\n                    then\n                        quest:setLocalVar(player, 'nmDefeated', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Nevela'] = quest:event(10018):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/A_Clock_Most_Delicate.lua"]={["Path"]="scripts/quests/jeuno/A_Clock_Most_Delicate.lua",["SHA256"]="d4bf1b7c5e4ac47bb46aeccd27bcc09ce7b1c77bacfe60732ee8f835aefe3ca1",["Text"]="-----------------------------------\n-- A Clock Most Delicate\n-----------------------------------\n-- Log ID: 3, Quest ID: 2\n-- Collet : !pos -44 0 107 244\n-- _6s2   : !pos -80 0 104 244\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.A_CLOCK_MOST_DELICATE)\n\nquest.reward =\n{\n    gil      = 1200,\n    item     = xi.item.ENGINEERS_GLOVES,\n    title    = xi.title.PROFESSIONAL_LOAFER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 2\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['_6s2'] =\n            {\n                onTrigger = function(player, npc)\n                    local questOption = quest:getVar(player, 'Option')\n\n                    if questOption == 1 then\n                        return quest:progressEvent(119)\n                    elseif questOption == 2 then\n                        return quest:progressEvent(118)\n                    end\n                end,\n            },\n\n            ['Collet'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(112)\n                    else\n                        return quest:event(186)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [112] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n\n                [118] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n\n                [119] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Option', 2)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['_6s2'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.CLOCK_TOWER_OIL) then\n                        return quest:progressEvent(202)\n                    else\n                        return quest:event(117)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [202] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 17)\n                        player:addFame(xi.fameArea.BASTOK, 17)\n                        player:addFame(xi.fameArea.WINDURST, 17)\n                        player:delKeyItem(xi.keyItem.CLOCK_TOWER_OIL)\n                    end\n                end,\n            },\n        },\n    }\n}\n\nreturn quest\n"},["scripts/quests/jeuno/A_Minstrel_In_Despair.lua"]={["Path"]="scripts/quests/jeuno/A_Minstrel_In_Despair.lua",["SHA256"]="1730666d3f1f1e8293ba5f49b957f4ff5622af35f2d64f0e9eea21d828faff58",["Text"]="-----------------------------------\n-- A Minstrel in Despair\n-----------------------------------\n-- Log ID: 3, Quest ID: 12\n-- Mertaire : !pos -17 0 -61 245\n-----------------------------------\nlocal buburimuID   = zones[xi.zone.BUBURIMU_PENINSULA]\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.A_MINSTREL_IN_DESPAIR)\n\nquest.reward =\n{\n    gil      = 2100,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_OLD_MONUMENT) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        -- Failsafe incase the player loses their Poetic Parchment\n        [xi.zone.BUBURIMU_PENINSULA] =\n        {\n            ['Song_Runes'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.SHEET_OF_PARCHMENT) then\n                        return quest:progressCutscene(2)\n                    end\n                end,\n\n                onTrigger = quest:messageSpecial(buburimuID.text.SONG_RUNES_REQUIRE, xi.item.SHEET_OF_PARCHMENT),\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveItem(player, xi.item.POETIC_PARCHMENT)\n                    player:messageSpecial(buburimuID.text.SONG_RUNES_WRITING, xi.item.SHEET_OF_PARCHMENT)\n                end,\n            },\n        },\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n\n            ['Bki_Tbujhja'] = quest:event(182),\n\n            ['Mataligeat'] = quest:event(144),\n\n            ['Mertaire'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { xi.item.POETIC_PARCHMENT }) then\n                        return quest:progressEvent(101)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:messageName(lowerJeunoID.text.MERTAIRE_MALLIEBELL_LEFT, 0, 0, 0, 0, true, false)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [101] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:confirmTrade()\n                    end\n                end,\n            }\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/All_in_the_Cards.lua"]={["Path"]="scripts/quests/jeuno/All_in_the_Cards.lua",["SHA256"]="842a4ae486dee33221efc27bf8de116e33818d95f8bbfbb0578115f66057d8fd",["Text"]="-----------------------------------\n-- All in the Cards\n-----------------------------------\n-- Log ID: 3, Quest ID: 166\n-- Chululu : !pos -13 -6 -42 245\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.ALL_IN_THE_CARDS)\n\nquest.reward =\n{\n    gil   = 600,\n    title = xi.title.CARD_COLLECTOR,\n}\n\nlocal tarutCards =\n{\n    xi.item.TARUT_CARD_THE_FOOL,\n    xi.item.TARUT_CARD_DEATH,\n    xi.item.TARUT_CARD_THE_HERMIT,\n    xi.item.TARUT_CARD_THE_KING,\n}\n\nlocal function giveCards(player)\n    if npcUtil.giveItem(player, { { tarutCards[math.randomInt(1, #tarutCards)], 5 } }) then\n        quest:setVar(player, 'Date', JstMidnight())\n        return true\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COLLECT_TARUT_CARDS) == xi.questStatus.QUEST_COMPLETED and\n                GetSystemTime() > quest:getVar(player, 'Date')\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Chululu'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(10110) -- Offers the quest\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10110] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        giveCards(player)\n                    then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COLLECT_TARUT_CARDS) == xi.questStatus.QUEST_COMPLETED and\n                GetSystemTime() > quest:getVar(player, 'Date')\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Chululu'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(10113) -- Offers the quest again\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10113] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        giveCards(player)\n                    then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Chululu'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.TARUT_CARD_THE_FOOL, 1 }, { xi.item.TARUT_CARD_DEATH, 1 }, { xi.item.TARUT_CARD_THE_HERMIT, 1 }, { xi.item.TARUT_CARD_THE_KING, 1 } }) then\n                        return quest:progressEvent(10114) -- Finishes the quest\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if GetSystemTime() > quest:getVar(player, 'Date') then\n                        return quest:event(10112) -- A new batch of cards, once per Earth day\n                    else\n                        return quest:event(10111) -- Reminder\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10112] = function(player, csid, option, npc)\n                    giveCards(player)\n                end,\n\n                [10114] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 16)\n                        player:addFame(xi.fameArea.BASTOK, 16)\n                        player:addFame(xi.fameArea.WINDURST, 16)\n                        player:tradeComplete()\n                        quest:setVar(player, 'Date', JstMidnight()) -- Next offer waits for JST midnight\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Apocalypse_Nigh.lua"]={["Path"]="scripts/quests/jeuno/Apocalypse_Nigh.lua",["SHA256"]="2cdb7cb4e76d1fd8a606f5eaaa657bbd68e7d478b1b4ffdacb471fa81ae55387",["Text"]="-----------------------------------\n-- Apocalypse Nigh\n-----------------------------------\n-- Log ID: 3, Quest ID: 89\n-- _iya      : !pos -20 0.1 -283 34\n-- Aldo      : !pos 20 3 -58 245\n-- Gilgamesh : !pos 122.452 -9.009 -12.052 252\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.APOCALYPSE_NIGH)\n\nquest.reward = {}\n\nlocal rewardOnEventUpdate = function(player, csid, option, npc)\n    if option == 99 then\n        player:updateEvent(252,\n            xi.item.STATIC_EARRING,\n            xi.item.MAGNETIC_EARRING,\n            xi.item.HOLLOW_EARRING,\n            xi.item.ETHEREAL_EARRING\n        )\n    end\nend\n\n-- NOTE: This event is also captured in both Dawn and Awakening's mission scripts, and\n-- the order may not trigger after this function.  While the missions are guaranteed to\n-- complete here, the quest may not if inventory is full, but it will not errantly complete.\n-- Both missions require their variables to be cleared, and is why they are handled there.\n\nlocal rewardOnEventFinish = function(player, csid, option, npc)\n    if\n        option >= 1 and\n        option <= 4\n    then\n        local rewardItem = xi.item.STATIC_EARRING + option - 1\n\n        if npcUtil.giveItem(player, rewardItem) then\n            quest:complete(player)\n        end\n    else\n        quest:setVar(player, 'Prog', 6)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.SHADOWS_OF_THE_DEPARTED) and\n                VanadielUniqueDay() >= vars.Timer and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            onTriggerAreaEnter =\n            {\n                [1] = function(player, triggerArea)\n                    return quest:progressEvent(123)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [123] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SEALIONS_DEN] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 0 then\n                    return 29\n                end\n            end,\n\n            onEventUpdate =\n            {\n                [29] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:updateEvent(0, 0, 0, 0, 32, 3, 0, 0)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [29] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.GRAND_PALACE_OF_HUXZOI] =\n        {\n            ['_iya'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(4)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:setPos(-419.995, 0, 248.483, 191, 35)\n                end,\n            },\n        },\n\n        [xi.zone.EMPYREAL_PARADOX] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 4 then\n                    return 7\n                end\n            end,\n\n            ['TR_Entrance'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(4)\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [7] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:updateEvent(36, 1430550, 2964, 1013, 36, 1, 0, 0)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                -- The title comes with this cutscene, not the battlefield win.\n                [7] = function(player, csid, option, npc)\n                    player:addTitle(xi.title.BREAKER_OF_THE_CHAINS)\n                    player:setPos(-.0745, -10, -465.1132, 63, xi.zone.ALTAIEU)\n                end,\n\n                [32001] = function(player, csid, option, npc)\n                    if\n                        player:getLocalVar('battlefieldWin') == xi.battlefield.id.APOCALYPSE_NIGH and\n                        quest:getVar(player, 'Prog') == 3\n                    then\n                        quest:setVar(player, 'Prog', 4)\n                        quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Aldo'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        questProgress == 4 and\n                        player:getRank(player:getNation()) >= 5\n                    then\n                        return quest:progressEvent(10057)\n                    elseif questProgress == 5 then\n                        return quest:event(10058)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10057] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n\n        [xi.zone.NORG] =\n        {\n            ['_700'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 5 and\n                        quest:getVar(player, 'Timer') > VanadielUniqueDay()\n                    then\n                        return quest:progressEvent(235)\n                    end\n                end,\n            },\n\n            ['Gilgamesh'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        VanadielUniqueDay() >= quest:getVar(player, 'Timer') and\n                        not quest:getMustZone(player)\n                    then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 5 then\n                            return quest:progressEvent(232, 252, 6)\n                        elseif questProgress == 6 then\n                            return quest:progressEvent(234, 252)\n                        end\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [232] = rewardOnEventUpdate,\n                [234] = rewardOnEventUpdate,\n            },\n\n            onEventFinish =\n            {\n                [232] = rewardOnEventFinish,\n                [234] = rewardOnEventFinish,\n\n                [235] = function(player, csid, option, npc)\n                    quest:setMustZone(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.EMPYREAL_PARADOX] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    for itemId = xi.item.STATIC_EARRING, xi.item.STATIC_EARRING + 3 do\n                        if player:hasItem(itemId) then\n                            return\n                        end\n                    end\n\n                    return quest:progressEvent(5)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_LAST_VERSE)\n                        player:delMission(xi.mission.log_id.ZILART, xi.mission.id.zilart.THE_LAST_VERSE)\n\n                        player:addMission(xi.mission.log_id.COP, xi.mission.id.cop.DAWN)\n                        player:addMission(xi.mission.log_id.ZILART, xi.mission.id.zilart.AWAKENING)\n\n                        player:setMissionStatus(xi.mission.log_id.ZILART, 3)\n                        xi.mission.setVar(player, xi.mission.log_id.COP, xi.mission.id.cop.DAWN, 'Status', 8)\n\n                        player:delQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.SHADOWS_OF_THE_DEPARTED)\n                        player:delQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.APOCALYPSE_NIGH)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORG] =\n        {\n            ['Gilgamesh'] = quest:event(233):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Axe_the_Competition.lua"]={["Path"]="scripts/quests/jeuno/Axe_the_Competition.lua",["SHA256"]="2b926587357bf4c45239da10c99e89e99c256d9a22bdf160f6311f79ad1d5619",["Text"]="-----------------------------------\n-- Axe the Competition\n-- Brutus !pos -55 8 95 244\n-- qm9 !pos 218 -8 206 159\n-----------------------------------\nlocal upperJeunoID = zones[xi.zone.UPPER_JEUNO]\nlocal uggalepihID = zones[xi.zone.TEMPLE_OF_UGGALEPIH]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.AXE_THE_COMPETITION)\n\nquest.reward =\n{\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.PICK_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.AXE) / 10 >= 240 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(12):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        (player:hasItem(xi.item.PICK_OF_TRIALS) or npcUtil.giveItem(player, xi.item.PICK_OF_TRIALS))\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(17) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(16) -- cont 2\n                    else\n                        return quest:event(15, player:hasItem(xi.item.PICK_OF_TRIALS) and 1 or 0) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.PICK_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(14) -- unfinished weapon\n                        else\n                            return quest:progressEvent(13) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [15] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.PICK_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.PICK_OF_TRIALS)\n                    elseif option == 2 then\n                        player:delQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.AXE_THE_COMPETITION)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [17] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.DECIMATION)\n                        player:messageSpecial(upperJeunoID.text.DECIMATION_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.TEMPLE_OF_UGGALEPIH] =\n        {\n            ['qm9'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, uggalepihID.mob.YALLERY_BROWN, { hide = 0 })\n                    then\n                        return quest:messageSpecial(uggalepihID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Yallery_Brown'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Borghertzs_Calling_Hands.lua"]={["Path"]="scripts/quests/jeuno/Borghertzs_Calling_Hands.lua",["SHA256"]="29a1c8de4ff911125f78c8dadcd1bbcba37e9f4a26f4693dd6655131db94c5cc",["Text"]="-----------------------------------\n-- Borghertz's Calling Hands\n-----------------------------------\n-- Log ID: 3, Quest ID: 58\n-- Torch         : !pos  63 -24  21 161\n-- Guslam        : !pos  -5   1  48 244\n-- Deadly Minnow : !pos  -5   1  48 244\n-- Yin Pocanakhu : !pos  35   4 -43 245\n-- qm1           : !pos -51   8  -4 246\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\n\nlocal params =\n{\n    questId           = xi.quest.id.jeuno.BORGHERTZS_CALLING_HANDS,\n    handAFId          = xi.item.EVOKERS_BRACERS,\n    requiredLogId     = xi.questLog.WINDURST,\n    requiredQuestId   = xi.quest.id.windurst.CLASS_REUNION,\n    requiredJobId     = xi.job.SMN,\n    oldGauntletZoneId = xi.zone.SEA_SERPENT_GROTTO,\n    optionalZoneId1   = xi.zone.TEMPLE_OF_UGGALEPIH,\n    optionalZoneId2   = xi.zone.TORAIMARAI_CANAL,\n    optionalArtifact1 = xi.item.EVOKERS_DOUBLET,\n    optionalArtifact2 = xi.item.EVOKERS_PIGACHES,\n}\n\nlocal quest = xi.jeuno.helpers.BorghertzQuests:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/Borghertzs_Chasing_Hands.lua"]={["Path"]="scripts/quests/jeuno/Borghertzs_Chasing_Hands.lua",["SHA256"]="be789d5a12220ef7ffb3310eb1ced518bc3e337b7dc147a1ccf34b121e56a7fd",["Text"]="-----------------------------------\n-- Borghertz's Chasing Hands\n-----------------------------------\n-- Log ID: 3, Quest ID: 54\n-- Torch         : !pos  63 -24  21 161\n-- Guslam        : !pos  -5   1  48 244\n-- Deadly Minnow : !pos  -5   1  48 244\n-- Yin Pocanakhu : !pos  35   4 -43 245\n-- qm1           : !pos -51   8  -4 246\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\n\nlocal params =\n{\n    questId           = xi.quest.id.jeuno.BORGHERTZS_CHASING_HANDS,\n    handAFId          = xi.item.HUNTERS_BRACERS,\n    requiredLogId     = xi.questLog.WINDURST,\n    requiredQuestId   = xi.quest.id.windurst.FIRE_AND_BRIMSTONE,\n    requiredJobId     = xi.job.RNG,\n    oldGauntletZoneId = xi.zone.GARLAIGE_CITADEL,\n    optionalZoneId1   = xi.zone.CRAWLERS_NEST,\n    optionalZoneId2   = xi.zone.MONASTIC_CAVERN,\n    optionalArtifact1 = xi.item.HUNTERS_BRACCAE,\n    optionalArtifact2 = xi.item.HUNTERS_JERKIN,\n}\n\nlocal quest = xi.jeuno.helpers.BorghertzQuests:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/Borghertzs_Dragon_Hands.lua"]={["Path"]="scripts/quests/jeuno/Borghertzs_Dragon_Hands.lua",["SHA256"]="8923e3e9a26e48b440922877b9e2568adbec1d771012609c8aeb622db6f18611",["Text"]="-----------------------------------\n-- Borghertz's Dragon Hands\n-----------------------------------\n-- Log ID: 3, Quest ID: 57\n-- Torch         : !pos  63 -24  21 161\n-- Guslam        : !pos  -5   1  48 244\n-- Deadly Minnow : !pos  -5   1  48 244\n-- Yin Pocanakhu : !pos  35   4 -43 245\n-- qm1           : !pos -51   8  -4 246\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\n\nlocal params =\n{\n    questId           = xi.quest.id.jeuno.BORGHERTZS_DRAGON_HANDS,\n    handAFId          = xi.item.DRACHEN_FINGER_GAUNTLETS,\n    requiredLogId     = xi.questLog.SANDORIA,\n    requiredQuestId   = xi.quest.id.sandoria.CHASING_QUOTAS,\n    requiredJobId     = xi.job.DRG,\n    oldGauntletZoneId = xi.zone.THE_BOYAHDA_TREE,\n    optionalZoneId1   = xi.zone.IFRITS_CAULDRON,\n    optionalZoneId2   = xi.zone.QUICKSAND_CAVES,\n    optionalArtifact1 = xi.item.DRACHEN_MAIL,\n    optionalArtifact2 = xi.item.DRACHEN_GREAVES,\n}\n\nlocal quest = xi.jeuno.helpers.BorghertzQuests:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/Borghertzs_Harmonious_Hands.lua"]={["Path"]="scripts/quests/jeuno/Borghertzs_Harmonious_Hands.lua",["SHA256"]="44626dac6da2a56ded36bd468cb802ead8572d43c0b7c5638a3b4ee8cd18edd5",["Text"]="-----------------------------------\n-- Borghertz's Harmonious Hands\n-----------------------------------\n-- Log ID: 3, Quest ID: 53\n-- Torch         : !pos  63 -24  21 161\n-- Guslam        : !pos  -5   1  48 244\n-- Deadly Minnow : !pos  -5   1  48 244\n-- Yin Pocanakhu : !pos  35   4 -43 245\n-- qm1           : !pos -51   8  -4 246\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\n\nlocal params =\n{\n    questId           = xi.quest.id.jeuno.BORGHERTZS_HARMONIOUS_HANDS,\n    handAFId          = xi.item.CHORAL_CUFFS,\n    requiredLogId     = xi.questLog.JEUNO,\n    requiredQuestId   = xi.quest.id.jeuno.THE_REQUIEM,\n    requiredJobId     = xi.job.BRD,\n    oldGauntletZoneId = xi.zone.CASTLE_ZVAHL_BAILEYS,\n    optionalZoneId1   = xi.zone.CASTLE_OZTROJA,\n    optionalZoneId2   = xi.zone.CRAWLERS_NEST,\n    optionalArtifact1 = xi.item.CHORAL_CANNIONS,\n    optionalArtifact2 = xi.item.CHORAL_ROUNDLET,\n}\n\nlocal quest = xi.jeuno.helpers.BorghertzQuests:new(params)\n\nreturn quest\n"}};
